package com.profa.teacher;
import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="teacher_profiles") public class TeacherProfile { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(nullable=false,unique=true) private UUID userId;private String headline;@Column(length=5000) private String bio;private String city;private String district;private String address;private Integer hourlyRate;private Integer salaryExpectation;private String avatarUrl;private String introVideoUrl;private boolean verified;private Integer experienceYears;private String languages;private String availabilityJson;private Instant updatedAt=Instant.now();public UUID getId(){return id;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public String getHeadline(){return headline;}public void setHeadline(String v){headline=v;}public String getBio(){return bio;}public void setBio(String v){bio=v;}public String getCity(){return city;}public void setCity(String v){city=v;}public void setDistrict(String v){district=v;}public String getDistrict(){return district;}public void setAddress(String v){address=v;}public String getAddress(){return address;}public void setHourlyRate(Integer v){hourlyRate=v;}public Integer getHourlyRate(){return hourlyRate;}public void setSalaryExpectation(Integer v){salaryExpectation=v;}public Integer getSalaryExpectation(){return salaryExpectation;}public void setAvatarUrl(String v){avatarUrl=v;}public String getAvatarUrl(){return avatarUrl;}public void setIntroVideoUrl(String v){introVideoUrl=v;}public String getIntroVideoUrl(){return introVideoUrl;}public boolean isVerified(){return verified;}public void setVerified(boolean v){verified=v;}public void setExperienceYears(Integer v){experienceYears=v;}public Integer getExperienceYears(){return experienceYears;}public void setLanguages(String v){languages=v;}public String getLanguages(){return languages;}public void setAvailabilityJson(String v){availabilityJson=v;}public String getAvailabilityJson(){return availabilityJson;} }
